package handler

import "strings"

func assistantHTML(token string) string {
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font:14px system-ui;margin:0;background:#f8fafc}main{height:100vh;display:flex;flex-direction:column}.chat{flex:1;overflow:auto;padding:14px}.m{background:white;border-radius:8px;padding:10px;margin:8px 0;white-space:pre-wrap}.u{background:#dbeafe}form{display:flex;padding:10px;background:white;border-top:1px solid #ddd}input{flex:1;padding:10px}button{margin-left:8px;padding:10px}</style></head><body><main><div class="chat" id="chat"><div class="m">Ask a question about this organization’s documents.</div></div><form id="f"><input id="q" placeholder="Ask a question" required><button>Send</button></form></main><script>const token="` + strings.ReplaceAll(token, `"`, `\"`) + `",chat=document.getElementById('chat'),q=document.getElementById('q');function add(x,c){let d=document.createElement('div');d.className='m '+(c||'');d.textContent=x;chat.append(d);chat.scrollTop=chat.scrollHeight}document.getElementById('f').onsubmit=async e=>{e.preventDefault();let x=q.value.trim();if(!x)return;add(x,'u');q.value='';try{let r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json','X-Assistant-Token':token},body:JSON.stringify({question:x})}),j=await r.json();if(!r.ok)throw Error(j.error?.message||'Request failed');let refs=(j.data.references||[]).map(a=>a.document+' — Page '+a.page).join(', ');add(j.data.answer+(refs?'\n\nSources: '+refs:''))}catch(err){add(err.message)}};</script></body></html>`
}
